  "Once the blocking time window is {pct} percent full, cbase starts no new model work — no turn, no verdict — but parks it until the reset, regardless of the switch above. The chat then offers a button that releases this one turn, including its subagents.": "Ist das blockierende Zeitfenster zu {pct} Prozent voll, beginnt cbase keine neue Modellarbeit — kein Turn, kein Urteil — sondern parkt sie bis zum Reset, unabhängig vom Schalter darüber. Am Chat steht dann ein Knopf, der genau diesen einen Turn samt seiner Subagenten freigibt.",
  "cbase prevents the START — not the credit spend of work that is already running: the provider's server decides that. The hard stop lives in your account. Applies to Claude only: Codex reports its utilization only after a run, third-party providers have no windows.": "cbase verhindert den START — nicht den Guthabenverbrauch von Arbeit, die schon läuft: darüber entscheidet der Server des Anbieters. Die harte Sperre sitzt im Konto. Gilt nur für Claude: Codex meldet seine Auslastung erst nach dem Lauf, Dritt-Anbieter haben keine Fenster.",
