  "Controls the built-in browser (Playwright) the agent uses to open web pages and run end-to-end tests. In the background everything runs invisibly — no window opens.": "Steuert den eingebauten Browser (Playwright), mit dem der Agent Webseiten öffnet und End-to-End-Tests fährt. Im Hintergrund läuft alles unsichtbar — es öffnet sich kein Fenster.",
