  "The active provider applies to new chats and all AI side tasks (titles, architecture, context).": "Der aktive Anbieter gilt für neue Chats und alle KI-Nebenaufgaben (Titel, Architektur, Kontext).",
  "The active provider handles new chats and all AI side tasks (titles, context curation). Sign in here and switch between providers anytime.": "Der aktive Anbieter bedient neue Chats und alle KI-Nebenaufgaben (Titel, Kontext-Kuration). Melde dich hier an und wechsle jederzeit zwischen den Anbietern.",
