  "Session end": "Sitzungsende",
  "Shell commands the own harness (third-party providers like Nebius) runs at agent events — like in Claude Code. The command receives the event as JSON on stdin. PreToolUse can block a tool (exit code 2 or output {\"decision\":\"block\",\"reason\":…}); PostToolUse and UserPromptSubmit can add context (output {\"additionalContext\":…} or plain text). Claude/Codex use their own CLI hooks.": "Shell-Befehle, die der eigene Harness (Drittanbieter wie Nebius) an Agenten-Ereignissen ausführt — wie in Claude Code. Der Befehl erhält das Ereignis als JSON über stdin. PreToolUse kann ein Tool blockieren (Exit-Code 2 oder Ausgabe {\"decision\":\"block\",\"reason\":…}); PostToolUse und UserPromptSubmit können Zusatzkontext liefern (Ausgabe {\"additionalContext\":…} oder reiner Text). Claude/Codex nutzen ihre eigenen CLI-Hooks.",
  "Tool pattern (regex) or *": "Tool-Muster (RegExp) oder *",
  "Usage": "Nutzung",
  "Plan quotas": "Abo-Kontingente",
