  "Computing power": "Rechenleistung",
  "Spare computing power": "Rechenleistung schonen",
  "Commands of subagents, workflow and outer-loop agents and monitors run at lower CPU priority, and under full load a new command of theirs waits up to two minutes — a chat's main agent never does.": "Befehle von Subagenten, Workflow- und Outer-Loop-Agenten und Monitoren laufen mit niedrigerer CPU-Priorität, und bei voller Last wartet ein neuer Befehl von ihnen bis zu zwei Minuten — der Hauptagent eines Chats nie.",
  "waiting for CPU": "wartet auf CPU",
  "Dynamic workflow size": "Größe dynamischer Workflows",
  "How large the agent plans dynamic workflows — a hint to the model, not a hard limit. Independently, a run with more than 25 agents or 1.5M tokens gets a warning (not in Ultracode mode). A hard ceiling is set by “+500k” in the message.": "Wie groß der Agent dynamische Workflows plant — ein Hinweis an das Modell, keine harte Grenze. Unabhängig davon warnt ein Lauf mit mehr als 25 Agenten oder 1,5 Mio. Token (im Modus Ultracode nicht). Eine harte Obergrenze setzt „+500k“ in der Nachricht.",
  "Small (under 5 agents)": "Klein (unter 5 Agenten)",
  "Medium (under 10 agents)": "Mittel (unter 10 Agenten)",
  "Large (under 50 agents)": "Groß (unter 50 Agenten)",
  "Unrestricted": "Unbegrenzt",
  "At most this many agents run at the same time, across all workflows together (default {n}). The rest wait and start as soon as a slot frees up. A single run is additionally limited to {run}.": "Höchstens so viele Agenten laufen gleichzeitig, über alle Workflows zusammen (Vorgabe {n}). Überzählige warten und starten, sobald ein Platz frei wird. Ein einzelner Lauf ist zusätzlich auf {run} begrenzt.",
