  "Summarizes the history on /compact. Auto = the respective chat's model.": "Fasst den Verlauf bei /compact zusammen. Auto = Modell des jeweiligen Chats.",
  "Context curator": "Kontext-Kurator",
  "Routes dumpster drops into projects and merges project context.": "Sortiert Dumpster-Einwürfe in Projekte ein und pflegt Projekt-Kontext zusammen.",
  "Context classification": "Kontext-Klassifikation",
  "Assigns dropped snippets to a category (title, summary, tags). Auto = the active provider's default model.": "Ordnet eingeworfene Schnipsel einer Kategorie zu (Titel, Zusammenfassung, Tags). Auto = Standardmodell des aktiven Anbieters.",
  "Service scan": "Dienste-Scan",
  "Inventories a project's stack (services, ports) on creation or re-scan.": "Inventarisiert den Stack eines Projekts (Dienste, Ports) bei Anlage bzw. Re-Scan.",
  "Adjust text": "Text anpassen",
  "Rephrases selected text according to your instruction (“Adjust” on an approval card) and puts the result on the clipboard. One short call per adjustment, sandboxed — a fast model is enough.": "Formuliert markierten Text nach deiner Anweisung um („Anpassen“ an einer Freigabe-Karte) und legt das Ergebnis in die Zwischenablage. Ein kurzer Aufruf je Anpassung, abgeschottet — ein schnelles Modell genügt.",
  "Auto (chat model)": "Auto (Chat-Modell)",
  "Auto (provider default)": "Auto (Anbieter-Standard)",
  "The selected model is no longer on the list. Whether it still goes out or “Auto” takes over is decided only by the next run — only a new choice is reliable.": "Gewähltes Modell steht nicht mehr zur Auswahl. Ob es weiter hinausgeht oder „Auto“ greift, entscheidet erst der nächste Lauf — verlässlich ist nur eine neue Wahl.",
  "Chat replies are unaffected — you pick their model per chat in the composer.": "Chat-Antworten sind hiervon unberührt — deren Modell wählst du pro Chat im Composer.",
  "The folder dialog is only available in the app — please type the path.": "Der Ordner-Dialog ist nur in der App verfügbar — bitte den Pfad eintippen.",
