  "Your own MCP servers for this project (other projects don't see them; workspace chats do). The workspace servers below apply in every project and can be hidden here for this project. In this project's chats the agent has access to its own servers and the ones not hidden — effective from the next run.": "Eigene MCP-Server für dieses Projekt (andere Projekte sehen sie nicht; Workspace-Chats schon). Die Workspace-Server unten gelten in jedem Projekt und lassen sich hier für dieses Projekt ausblenden. In Chats dieses Projekts stehen dem Agenten die eigenen und die nicht ausgeblendeten Server zur Verfügung — wirksam ab dem nächsten Lauf.",
