  "Edit provider": "Anbieter bearbeiten",
  "Inherit from chat": "Vom Chat erben",
    "A provider from the list starts the subagent there — even when the chat runs on another provider (via cbase_agent that works from any chat). Only the Claude CLI's built-in Agent tool cannot; there the subagent inherits the chat model.": "Ein Anbieter aus der Liste startet den Subagenten dort — auch wenn der Chat bei einem anderen Anbieter läuft (über cbase_agent geht das aus jedem Chat). Nur das eingebaute Agent-Tool der Claude-CLI kann das nicht; dort erbt der Subagent das Chat-Modell.",
  "Skills (loaded in full at start)": "Skills (werden beim Start vollständig geladen)",
  "Checked skills are placed in full into the subagent's system prompt — it does not need to fetch them with cbase_skill. Each one costs its full length on every start.": "Angekreuzte Skills stehen dem Subagenten komplett im System-Prompt — er muss sie nicht mit cbase_skill holen. Jeder kostet bei jedem Start seine volle Länge.",
  "No skills here yet — create them under Coding → Skills.": "Hier gibt es noch keine Skills — anlegen unter Coding → Skills.",
  "This skill no longer exists here — starting the subagent will fail because of it.": "Diesen Skill gibt es hier nicht mehr — der Start des Subagenten schlägt damit fehl.",
  "Skills:": "Skills:",
  "Standing permissions": "Dauerhafte Freigaben",
  "Tool calls that go through without asking in the \"Ask\" and \"Auto-edit\" modes. They usually come from \"Always allow\" on the permission card. Same notation as Claude Code: Bash(git status:*) allows everything starting like that, Read(src/**) a path area, WebFetch the whole tool.": "Tool-Aufrufe, die in den Modi „Fragen\" und „Auto-Edit\" ohne Rückfrage durchgehen. Entstehen normalerweise über „Immer erlauben\" auf der Freigabe-Karte. Schreibweise wie in Claude Code: Bash(git status:*) erlaubt alles, was so beginnt; Read(src/**) einen Pfadbereich; WebFetch das ganze Tool.",
  "No standing permissions — every sensitive call asks.": "Keine dauerhaften Freigaben — es wird bei jedem heiklen Aufruf gefragt.",
  "Web search": "Websuche",
  "Source for the WebSearch tool of the built-in harness (third-party chats). Without a key it scrapes DuckDuckGo's HTML page, which breaks as soon as that page changes. Claude and Codex use their own search.": "Quelle für das WebSearch-Tool des eigenen Harness (Drittanbieter-Chats). Ohne Schlüssel wird die HTML-Seite von DuckDuckGo ausgewertet — das bricht, sobald sie sich ändert. Claude und Codex nutzen ihre eigene Suche.",
  "DuckDuckGo (no key, best effort)": "DuckDuckGo (ohne Schlüssel, Best-Effort)",
