  "A workflow is a graph of steps the agent works through one at a time. Selectable in a chat as long as no message has been sent. Off by default in projects (adopt them there individually).": "Ein Workflow ist ein Graph aus Schritten, den der Agent Schritt für Schritt abarbeitet. Im Chat wählbar, solange noch keine Nachricht gesendet wurde. In Projekten standardmäßig aus (dort gezielt übernehmbar).",
