  "Max. items": "Max. Elemente",
  "Command first": "Command davor",
  "Runs first when the step is reached. cbase executes /clear and /compact itself, a /skill loads that skill, anything else goes to the agent as a message. Placeholders allowed.": "Läuft beim Erreichen zuerst. /clear und /compact führt cbase selbst aus, ein /skill lädt den Skill, alles andere geht als Nachricht an den Agenten. Platzhalter erlaubt.",
  "/clear, /compact or a message": "/clear, /compact oder Nachricht",
  "Clear the context before the step runs": "Kontext leeren, bevor der Schritt läuft",
  "Compact the context before the step runs": "Kontext zusammenfassen, bevor der Schritt läuft",
  "Rounds per run": "Runden je Lauf",
  "How often this step may run in ONE run. Empty = the largest value set in the loop, otherwise the default ({n}). At the cap the run stops and asks.": "Wie oft dieser Schritt in EINEM Lauf laufen darf. Leer = der größte im Kreis gesetzte Wert, sonst der Standard ({n}). Am Deckel hält der Lauf an und fragt.",
  "{n} · from {from}": "{n} · von {from}",
  "{n} · default": "{n} · Standard",
  "Continue past the cap without asking": "Am Deckel ohne Rückfrage weiter",
  "Instead of asking, the run leaves the loop and continues at “{exit}”.": "Statt zu fragen verlässt der Lauf die Schleife und arbeitet bei „{exit}“ weiter.",
  "Instead of asking, the run leaves the loop — this loop has no exit yet, so the run would end there.": "Statt zu fragen verlässt der Lauf die Schleife — diese Schleife hat noch keinen Ausgang, der Lauf endete dort.",
  "Applies to the completion check as well: after {n} rounds it continues without asking.": "Gilt auch für die Prüfung der Fertigstellung: nach {n} Runden geht es ohne Rückfrage weiter.",
  "After the turn, a model judges whether the step is finished; “not finished” means the same step keeps working. Costs one short model call per round.": "Nach dem Turn urteilt ein Modell, ob der Schritt erledigt ist; „nicht fertig“ heißt: derselbe Schritt arbeitet weiter. Kostet je Runde einen kurzen Modellaufruf.",
  "Yardstick (optional)": "Maßstab (optional)",
  "Empty = this step's own instruction": "Leer = der Auftrag dieses Schritts",
  "Notify when the review is due": "Mitteilung, wenn das Review ansteht",
  "Notify on arrival": "Mitteilung beim Erreichen",
  "Bell and iPhone notification, leads into this chat. Without it the run waits silently.": "Glocke und iPhone-Mitteilung, führt in diesen Chat. Ohne Mitteilung wartet der Lauf still.",
  "Bell and iPhone notification, leads into this chat.": "Glocke und iPhone-Mitteilung, führt in diesen Chat.",
  "One turn writes the request and the test instructions, then the run waits for you. Findings → back into fixing, approval → onward.": "Ein Turn schreibt Anfrage und Testanleitung, dann wartet der Lauf auf dich. Befunde → zurück in die Behebung, Freigabe → weiter.",
  "Every outgoing edge is a branch; all run in ONE turn, one subagent each, and meet at the shared target node.": "Jede ausgehende Kante ist ein Zweig; alle laufen in EINEM Turn, je Zweig ein Subagent, und treffen sich an der gemeinsamen Ziel-Node.",
  "A small model judges and picks yes or no.": "Ein kleines Modell urteilt und wählt Ja oder Nein.",
