  "Shows events from the last 24 hours that would trigger — without starting anything and without consuming events. Once armed, only new ones count.": "Zeigt Ereignisse der letzten 24 Stunden, die auslösen würden — ohne etwas zu starten und ohne Ereignisse zu verbrauchen. Scharfgestellt zählen dann nur neue.",
  "Nothing new — the trigger is waiting.": "Nichts Neues — der Trigger wartet.",
  "Placeholders": "Platzhalter",
  "Kind of event, e.g. “New merge request”": "Art des Ereignisses, z. B. „Neuer Merge Request“",
  "Title of the merge request or work item": "Titel des Merge Requests oder Work Items",
  "Link to the item in GitLab": "Link zum Gegenstand in GitLab",
  "Path of the project": "Pfad des Projekts",
  "who triggered the event": "wer das Ereignis ausgelöst hat",
  "affected branch": "betroffener Branch",
