  "Integrations": "Integrationen",
  "Connected accounts for workflow triggers: cbase polls GitLab regularly and starts workflows on new merge requests, work items, comments, pushes or pipelines.": "Verbundene Konten für Workflow-Trigger: cbase fragt GitLab regelmäßig ab und startet Workflows bei neuen Merge Requests, Work Items, Kommentaren, Pushes oder Pipelines.",
  "No GitLab account connected yet.": "Noch kein GitLab-Konto verbunden.",
  "token stored": "Token hinterlegt",
