  "Connect GitLab": "GitLab verbinden",
  "+ Connect GitLab": "+ GitLab verbinden",
  "Name (free-form)": "Name (frei)",
  "e.g. company GitLab": "z. B. Firmen-GitLab",
  "Personal access token": "Personal Access Token",
  "Create one in GitLab under Profile → Access Tokens. read_api is enough for listening; use api if the agent should also write (comments, MRs).": "In GitLab unter Profil → Access Tokens erzeugen. Zum Lauschen genügt read_api; soll der Agent auch schreiben (Kommentare, MRs), nimm api.",
  "The token stays on this machine (or in your server environment) and is never returned to the interface.": "Das Token bleibt auf diesem Rechner (bzw. in deiner Server-Umgebung) und wird nie an die Oberfläche zurückgegeben.",
  "Connection works — @{user}": "Verbindung steht — @{user}",
  "Remove account “{name}”? Triggers using it will stop firing.": "Konto „{name}“ entfernen? Trigger, die es benutzen, lösen dann nicht mehr aus.",
  "New access token for {name}:": "Neues Access-Token für {name}:",

  "ngrok": "ngrok",
  "Preview links: a project's service becomes reachable at a public address through your ngrok account — for showing and testing with others. Links are created in the services list of the header.": "Vorschau-Links: ein Dienst eines Projekts wird über dein ngrok-Konto unter einer öffentlichen Adresse erreichbar — zum Zeigen und Testen für Dritte. Angelegt wird ein Link in der Dienste-Liste der Kopfzeile.",
  "The ngrok module is missing in this cbase environment — links can't be created here.": "Das ngrok-Modul fehlt in dieser cbase-Umgebung — Links lassen sich hier nicht anlegen.",
  "The ngrok module is missing in this cbase environment.": "Das ngrok-Modul fehlt in dieser cbase-Umgebung.",
  "With API key: each link gets its own name, up to {n} at a time.": "Mit API-Key: je Link ein eigener Name, bis zu {n} gleichzeitig.",
  "Authtoken only: always the same dev address, one link at a time.": "Nur Authtoken: immer dieselbe Dev-Adresse, ein Link zur Zeit.",
  "cbase can't see your ngrok plan. On Hobbyist or higher, create a key in the ngrok dashboard under “API Keys” and enter it below — then every new link gets a name of its own, up to three at a time.": "cbase sieht deinen ngrok-Plan nicht. Ab Hobbyist im ngrok-Dashboard unter „API Keys“ einen Key anlegen und unten eintragen — dann bekommt jeder neue Link einen eigenen Namen, bis zu drei gleichzeitig.",
  "still on the dev address — create it again for a name of its own": "noch auf der Dev-Adresse — für einen eigenen Namen neu anlegen",
  "Accounts": "Konten",
  "Preview links": "Vorschau-Links",
