  "Authtoken in the ngrok dashboard under “Your Authtoken”, API key under “API Keys”. Both stay in your cbase environment and are never returned to the interface.": "Authtoken im ngrok-Dashboard unter „Your Authtoken“, API-Key unter „API Keys“. Beide bleiben in deiner cbase-Umgebung und werden nie an die Oberfläche zurückgegeben.",
