  "Concurrency": "Nebenläufigkeit",
  "Every run holds a lock. Whoever doesn't get it waits until the holder is done: triggered events queue up by themselves, a manual start is rejected.": "Jeder Lauf hält eine Sperre. Wer sie nicht bekommt, wartet, bis der Halter fertig ist: ausgelöste Ereignisse reihen sich von selbst ein, ein Start von Hand wird abgelehnt.",
  "One run per project/repo": "Ein Lauf je Projekt/Repo",
  "Recommended: within the same repo the second run waits, different repos still run in parallel.": "Empfohlen: im selben Repo wartet der zweite Lauf, verschiedene Repos laufen weiter parallel.",
  "One run per workflow": "Ein Lauf je Workflow",
  "This workflow only ever runs once at a time — no matter which repo is affected.": "Dieser Workflow läuft immer nur einmal gleichzeitig — egal, welches Repo betroffen ist.",
  "One run per issue/MR": "Ein Lauf je Issue/MR",
  "Never the same subject twice. Different issues will then run at the same time in the same folder, though.": "Derselbe Gegenstand nie doppelt. Verschiedene Issues laufen dann aber gleichzeitig im selben Ordner.",
  "Custom key": "Eigener Schlüssel",
  "A template with the same placeholders as a step's text.": "Vorlage mit denselben Platzhaltern wie ein Schritt-Text.",
  "No lock": "Keine Sperre",
  "Everything may run at once — only sensible if the runs don't touch anything shared.": "Alles darf gleichzeitig laufen — nur sinnvoll, wenn die Läufe nichts Gemeinsames anfassen.",
  "Currently locked: {keys}": "Gerade gesperrt: {keys}",
  "locking": "sperrt",
  "A run of this workflow holds the lock {keys} — others are waiting.": "Ein Lauf dieses Workflows hält die Sperre {keys} — weitere warten.",
  "This run holds the lock {key} — other runs are waiting for it.": "Dieser Lauf hält die Sperre {key} — weitere Läufe warten darauf.",
  "sequential per project": "nacheinander je Projekt",
  "sequential per workflow": "nacheinander je Workflow",
  "sequential per issue/MR": "nacheinander je Issue/MR",
  "sequential per custom key": "nacheinander je eigenem Schlüssel",
  "parallel allowed": "parallel erlaubt",

  "Run settings": "Lauf-Einstellungen",
  "Apply to EVERY run of this workflow — including triggered ones, which have no user. Empty means “as usual”. A manual run switches its chat accordingly.": "Gelten für JEDEN Lauf dieses Workflows — auch für ausgelöste, die keinen Nutzer haben. Leer heißt „wie sonst\". Ein Lauf von Hand stellt seinen Chat entsprechend um.",
  "Provider": "LLM-Anbieter",
  "Default (global)": "Standard (global)",
  "Provider's default": "Standard des Anbieters",
  "Permissions": "Rechte",
  "As in the chat": "Wie im Chat",
  "Plan (read-only)": "Plan (nur lesen)",
  "Automatic": "Automatisch",
  "Every step runs with Ultracode: multi-agent orchestration without asking — the effort above applies unchanged.": "Jeder Schritt läuft mit Ultracode: Multi-Agenten-Orchestrierung ohne Rückfrage — der Effort darüber gilt unverändert.",
  "Completion judged by": "Fertigstellung prüft",
  "Internal task “Workflow verdicts” (Settings → Models)": "Interne Aufgabe „Workflow-Urteile“ (Einstellungen → Modelle)",
  "Judges, at steps with “Check completion”, whether the step is finished after the turn — independent of the agent's model. Conditions and lists are still judged by the internal task “Workflow verdicts”.": "Urteilt an Schritten mit „Fertigstellung prüfen“ nach dem Turn, ob der Schritt erledigt ist — unabhängig vom Modell des Agenten. Weichen und Listen urteilt weiterhin die interne Aufgabe „Workflow-Urteile“.",
  "Workflow verdicts": "Workflow-Urteile",
  "Decides conditions in running workflows, produces loop lists, interprets answers at the round cap and checks a step's completion. One short call per verdict; the completion-check model can be overridden per workflow in its run settings.": "Entscheidet in laufenden Workflows die Weichen, erzeugt Schleifen-Listen, deutet Antworten am Runden-Deckel und prüft die Fertigstellung eines Schritts. Ein kurzer Aufruf je Urteil; das Modell der Fertigstellungs-Prüfung lässt sich je Workflow in dessen Lauf-Einstellungen überstimmen.",
  "Entry for manual runs — the workflow begins here. Without a start it begins at the first step that has no incoming edge.": "Einstieg für Läufe von Hand — der Workflow beginnt hier. Ohne Start beginnt er beim ersten Schritt ohne eingehende Kante.",

