  "No description": "Ohne Beschreibung",
  "The main agent handed off subtasks. They run alongside, and their results land in the chat by themselves.": "Der Hauptagent hat Teilaufgaben abgegeben. Sie laufen nebenher; ihre Ergebnisse landen von selbst im Chat.",
  "No description — foreground subtasks only name their task in the transcript.": "Ohne Beschreibung — Vordergrund-Teilaufgaben nennen ihren Auftrag erst im Verlauf.",
  "Keeps running alongside while the chat stays responsive. As soon as it finishes, the agent evaluates the result on its own.": "Läuft nebenher weiter, während der Chat ansprechbar bleibt. Sobald es fertig ist, wertet der Agent das Ergebnis von selbst aus.",
  "The chat is woken at the given time by itself — until then you can keep writing.": "Der Chat wird zur genannten Zeit von selbst geweckt — bis dahin kannst du weiterschreiben.",

