  "waiting for a free slot · {n} at a time": "wartet auf einen freien Platz · {n} gleichzeitig",
  "Cap per workflow: {n} at a time. The agent starts as soon as a slot frees up.": "Deckel je Workflow: {n} gleichzeitig. Der Agent startet, sobald ein Platz frei wird.",
  "waiting · {n} per user": "wartet · {n} je Nutzer",
  "waiting for a free slot · {n} per user": "wartet auf einen freien Platz · {n} je Nutzer",
  "Cap across all workflows: {n} at a time (setting “Concurrent workflow agents”). The agent starts as soon as a slot frees up.": "Deckel über alle Workflows: {n} gleichzeitig (Einstellung „Gleichzeitige Workflow-Agenten“). Der Agent startet, sobald ein Platz frei wird.",
  "waiting for a slot": "wartet auf Platz",
  "All slots are taken — the agent starts as soon as one frees up.": "Alle Plätze sind belegt — der Agent startet, sobald einer frei wird.",
  "waiting · prompt cache": "wartet · Prompt-Cache",
  "Agents with the same model start staggered: the first writes the prompt cache, the others read it afterwards.": "Agenten mit demselben Modell starten versetzt: der erste schreibt den Prompt-Cache, die übrigen lesen ihn danach.",
  "waiting · limit": "wartet · Limit",
  "The provider is at its usage limit — it continues after the reset.": "Der Anbieter steht am Nutzungslimit — es geht nach dem Reset weiter.",
  "waiting · credit gate": "wartet · Guthaben-Gate",
  "waiting at the credit gate": "wartet am Guthaben-Gate",
  "The credit gate holds back new starts — the agent starts after the window resets.": "Das Guthaben-Gate hält neue Starts an — der Agent startet nach dem Reset des Fensters.",
  "waiting · project": "wartet · Projekt",
  "waiting for the project": "wartet auf das Projekt",
  "The project's container is not ready yet — the agent starts as soon as it is.": "Der Container des Projekts ist noch nicht bereit — der Agent startet, sobald er es ist.",
  "waiting · memory": "wartet · Speicher",
  "waiting for free memory": "wartet auf freien Speicher",
  "Memory is tight (container above 80 % of its limit or host below 20 % free) — the agents start one after another as soon as there is room again.": "Der Speicher ist knapp (Container über 80 % seiner Grenze oder Host unter 20 % frei) — die Agenten starten einer nach dem anderen, sobald wieder Platz ist.",
  "waiting · {reason}": "wartet · {reason}",
  "fewer log() lines": "weniger log()-Zeilen",
  "{n} older workflows of this chat are not shown.": "{n} ältere Workflows dieses Chats sind nicht gezeigt.",
  "{n} older log() lines": "{n} ältere log()-Zeilen",
  "Duration": "Laufzeit",
