  "What should the agent know?": "Was soll der Agent wissen?",
  "⌘⏎ sends. The agent sees it as “Message from the human”.": "⌘⏎ sendet. Beim Agenten steht sie als „Nachricht vom Menschen“.",
  "Write this agent a message — also a waiting one: it then reads it when it starts.": "Diesem Agenten eine Nachricht schreiben — auch einem wartenden: dann liest er sie beim Start.",
  "Write this subagent a message — even while the chat is idle.": "Diesem Subagenten eine Nachricht schreiben — auch wenn der Chat gerade ruht.",
