  "No input": "Ohne Eingabe",
  "Stop this graph workflow — its chat halts, and the main agent is told.": "Diesen Graph-Workflow stoppen — sein Chat hält an, und der Hauptagent erfährt es.",
  "Open this graph workflow's chat — that is where it runs, and where you can write to it.": "Den Chat dieses Graph-Workflows öffnen — dort läuft er, und dort kannst du ihm schreiben.",
  "Completion check": "Abschlussprüfung",
