  "Answer failed: {msg}": "Antwort fehlgeschlagen: {msg}",
  "This is no longer open — someone has already answered (on another device, perhaps). Reloading the state.": "Das ist nicht mehr offen — jemand hat schon geantwortet (etwa auf einem anderen Gerät). Der Stand wird neu geladen.",
  "Belongs to this project": "Gehört diesem Projekt",
  "Comes from the workspace — edit it there": "Kommt aus dem Workspace — bearbeitet wird er dort",
  "Agent types the agent in a chat starts as subagents.": "Agententypen, die der Agent im Chat als Subagenten startet.",
  "Agent types the agent in a chat starts as subagents. Available across the workspace and active automatically in new projects — switch them off there one by one.": "Agententypen, die der Agent im Chat als Subagenten startet. Workspace-weit verfügbar und in neuen Projekten automatisch aktiv — dort einzeln abschaltbar.",
  "Only in this project's chats and in workspace chats — other projects don't see them.": "Nur in Chats dieses Projekts und in Workspace-Chats — andere Projekte sehen sie nicht.",
  "New projects adopt them automatically — switch them off for this project here. Edit them at workspace level.": "Neue Projekte übernehmen sie automatisch — hier für dieses Projekt abschalten. Bearbeiten auf Workspace-Ebene.",
  "Accent color": "Akzentfarbe",
  "Colors buttons, selections, links and highlights across the app — on this device only. The dark theme uses a lighter shade, the light theme a deeper one where needed, so white text on it stays readable.": "Färbt Knöpfe, Auswahl, Links und Markierungen in der ganzen App — nur auf diesem Gerät. Im dunklen Design gilt eine hellere Stufe, im hellen bei Bedarf eine kräftigere, damit weißer Text darauf lesbar bleibt.",
  "Indigo": "Indigo",
