  "A highlighted surface — this is how running work and open proposals appear.": "Eine hervorgehobene Fläche — so stehen laufende Arbeit und offene Vorschläge da.",
  "Instance": "Instanz",
  "{n} file(s) with unsaved changes — they are lost when you switch the instance. Switch anyway?": "{n} Datei(en) mit ungespeicherten Änderungen — beim Wechsel der Instanz gehen sie verloren. Trotzdem wechseln?",
  "The copy {name} no longer exists — the editor shows the main instance again.": "Die Kopie {name} gibt es nicht mehr — der Editor zeigt wieder das Haupt.",
  "The copy {name} is not ready ({state}) — the editor shows the main instance.": "Die Kopie {name} ist nicht bereit ({state}) — der Editor zeigt das Haupt.",
  "The copy {name} is not ready right now ({state}) — the editor stays with it and continues once it is ready.": "Die Kopie {name} ist gerade nicht bereit ({state}) — der Editor bleibt bei ihr und arbeitet weiter, sobald sie bereit ist.",
  "The copy {name} is gone — {n} file(s) with unsaved changes stay open, but they can no longer be saved. Copy what you need, then switch to the main instance.": "Die Kopie {name} ist nicht mehr da — {n} Datei(en) mit ungespeicherten Änderungen bleiben offen, speichern geht nicht mehr. Kopiere, was du brauchst, dann wechsle zum Haupt.",
  "{n} file(s) with unsaved changes will be lost. Switch to the main instance?": "{n} Datei(en) mit ungespeicherten Änderungen gehen verloren. Zum Haupt wechseln?",
  "Switch to main": "Zum Haupt wechseln",
  "The project list could not be loaded — whether the copy {name} still exists is unknown. The editor shows the main instance.": "Die Projektliste ließ sich nicht laden — ob die Kopie {name} noch da ist, ist offen. Der Editor zeigt das Haupt.",
