  "The copy {name} is not ready right now ({state}) — the page stays with it and shows its services as soon as it is ready.": "Die Kopie {name} ist gerade nicht bereit ({state}) — die Seite bleibt bei ihr und zeigt ihre Dienste, sobald sie bereit ist.",
