  "The project list could not be loaded — whether the copy {name} still exists is unknown. The page shows the main instance.": "Die Projektliste ließ sich nicht laden — ob die Kopie {name} noch da ist, ist offen. Die Seite zeigt das Haupt.",
  "Choose instance: {instance}": "Instanz wählen: {instance}",
