  "This chat's copy changed — Git follows the chat again.": "Die Kopie dieses Chats hat sich geändert — Git folgt wieder dem Chat.",
  "The copy {name} is not ready ({state}) — Git shows this chat's instance again.": "Die Kopie {name} ist nicht bereit ({state}) — Git zeigt wieder die Instanz dieses Chats.",
