  "The copy {name} no longer exists — Git shows this chat's instance again.": "Die Kopie {name} gibt es nicht mehr — Git zeigt wieder die Instanz dieses Chats.",
  "The chosen instance no longer exists — Git shows this chat's instance again.": "Die gewählte Instanz gibt es nicht mehr — Git zeigt wieder die Instanz dieses Chats.",

  "The copy {name} is being removed — {n} file(s) with unsaved changes stay open, but they can no longer be saved. Copy what you need, then switch to the main instance.": "Die Kopie {name} wird gerade abgeräumt — {n} Datei(en) mit ungespeicherten Änderungen bleiben offen, speichern geht nicht mehr. Kopiere, was du brauchst, dann wechsle zum Haupt.",
  "The copy {name} is not ready ({state}) — {n} file(s) with unsaved changes stay open, but they can no longer be saved. Copy what you need, then switch to the main instance.": "Die Kopie {name} ist nicht bereit ({state}) — {n} Datei(en) mit ungespeicherten Änderungen bleiben offen, speichern geht nicht mehr. Kopiere, was du brauchst, dann wechsle zum Haupt.",
  "The copy {name} no longer exists — {n} file(s) with unsaved changes stay open, but they can no longer be saved. Copy what you need, then switch to the main instance.": "Die Kopie {name} gibt es nicht mehr — {n} Datei(en) mit ungespeicherten Änderungen bleiben offen, speichern geht nicht mehr. Kopiere, was du brauchst, dann wechsle zum Haupt.",
