  "Stop reading##import": "Einlesen abbrechen",
  "{n} files are left out (dependencies, build output, .DS_Store).": "{n} Dateien bleiben weg (Abhängigkeiten, Build-Ausgaben, .DS_Store).",
  "After creating, this tab uploads the files — please keep it open until the row shows “ready”. An interrupted upload can be resumed.": "Nach dem Anlegen lädt dieser Tab die Dateien hoch — bitte offen lassen, bis die Zeile „bereit“ zeigt. Ein abgebrochener Upload lässt sich fortsetzen.",
  "The outline has errors — fix them first, then create.": "Die Gliederung hat Fehler — erst beheben, dann anlegen.",
  "Creating…": "Lege an…",
  "Name not allowed: {path}": "Name nicht erlaubt: {path}",
  "Two entries with the same target: {path}": "Zwei Einträge mit demselben Ziel: {path}",
  "The repo search cannot find a code repo here (too deep or below an excluded folder): {path}": "Hier findet die Repo-Suche kein Code-Repo (zu tief oder unter einem ausgenommenen Ordner): {path}",
  "More than {n} code repos": "Mehr als {n} Code-Repos",
