  "root": "Wurzel",
  "Not enough space on the server: {free} free, {needed} needed.": "Zu wenig Platz auf dem Server: {free} frei, {needed} nötig.",
  "An upload is already running for this source (in another tab?).": "Für diese Quelle läuft schon ein Upload (in einem anderen Tab?).",
