  "{n} files don't belong to this source and are left out. Resume anyway?": "{n} Dateien gehören nicht zu dieser Quelle und bleiben weg. Trotzdem fortsetzen?",
  "Take what has been uploaded so far? Whatever is still missing won't be in the project.": "Mit dem übernehmen, was schon hochgeladen ist? Was noch fehlt, kommt dann nicht ins Projekt.",
