  "{n} files have names the project does not accept (control characters or similar, often invisible system files such as “Icon” of a folder with a custom icon): {names}. Upload without them?": "{n} Dateien haben Namen, die das Projekt nicht annimmt (Steuerzeichen o. Ä., oft unsichtbare Systemdateien wie „Icon“ eines Ordners mit eigenem Symbol): {names}. Ohne sie hochladen?",
  "Upload without them": "Ohne sie hochladen",
  "Discard this upload? What is still on the server is deleted; what has already been placed into the project stays there.": "Diesen Upload verwerfen? Was noch beim Server liegt, wird gelöscht; was schon ins Projekt eingesetzt ist, bleibt dort.",
  "Overwrite replaces them with the uploaded ones, Skip leaves them as they are. Cancel discards the rest of the upload; files already placed stay in the project. Closing only pauses it.": "Überschreiben ersetzt sie durch die hochgeladenen, Überspringen lässt sie, wie sie sind. Abbrechen verwirft den Rest des Uploads; schon eingesetzte Dateien bleiben im Projekt. Schließen hält ihn nur an.",
  "Overwrite replaces them with the uploaded ones, Skip leaves them as they are. Cancel discards the upload; closing only pauses it.": "Überschreiben ersetzt sie durch die hochgeladenen, Überspringen lässt sie, wie sie sind. Abbrechen verwirft den Upload; Schließen hält ihn nur an.",
  "{title} in “{project}”": "{title} in „{project}“",
  "1 more question waiting": "1 weitere Frage wartet",
  "{n} more questions waiting": "{n} weitere Fragen warten",
  "To resume, drag the same folders and files onto this row again.": "Zum Fortsetzen dieselben Ordner und Dateien wieder auf diese Zeile ziehen.",
  "The server's rules have not loaded yet — try again in a moment.": "Die Regeln des Servers sind noch nicht geladen — gleich noch einmal versuchen.",
  "Folder “{name}”": "Ordner „{name}“",
  "1 file": "1 Datei",
  "{n} files": "{n} Dateien",
  "Nothing in this selection would be uploaded.": "In dieser Auswahl liegt nichts, was hochgeladen würde.",
  "ZIP “{name}”": "ZIP „{name}“",
  "Dropped files": "Abgelegte Dateien",
  "“{fresh}” cannot be shown to be the archive that is already partly uploaded. Discard the started upload and upload this archive from scratch?": "„{fresh}“ ist nicht nachweislich das Archiv, das schon teilweise hochgeladen ist. Den angefangenen Upload verwerfen und dieses Archiv neu hochladen?",
  "Upload from scratch": "Neu hochladen",
  "“{fresh}” is not the folder “{old}” that is already partly uploaded. Add it to this upload anyway?": "„{fresh}“ ist nicht der Ordner „{old}“, der schon teilweise hochgeladen ist. Trotzdem in diesen Upload laden?",
  "Discard this upload? Whatever of it is already on the server is deleted; nothing in the project changes.": "Diesen Upload verwerfen? Was davon schon beim Server liegt, wird gelöscht; im Projekt ändert sich nichts.",
