  "Stop {instance}? The containers shut down, the memory is freed, the data stays. The next turn of a chat starts it again.": "{instance} stoppen? Die Container gehen aus, der Speicher wird frei, die Daten bleiben. Der nächste Turn eines Chats startet sie wieder.",
