  "{run} of {total} running": "{run} von {total} laufen",
  "A copy is a separate instance of the project with its own containers and its own code. It belongs to no chat and lives until it is deleted.": "Eine Kopie ist eine eigene Instanz des Projekts mit eigenen Containern und eigenem Code. Sie gehört keinem Chat und lebt, bis sie gelöscht wird.",
  "Base": "Basis",
  "No instance is ready — a copy can only be made from a running instance.": "Keine Instanz ist bereit — eine Kopie entsteht nur aus einer laufenden Instanz.",
  "{who} · not ready": "{who} · nicht bereit",
  "{who} is not ready right now — choose another base or wait until it is ready.": "{who} ist gerade nicht bereit — wähle eine andere Basis oder warte, bis sie bereit ist.",
  "A copy carries over its whole state — open changes, index, reflogs and stashes; with a different branch, no repo carries over open changes. It pauses briefly for this.": "Aus einer Kopie kommt ihr ganzer Stand mit — offene Änderungen, Index, Reflogs und Stashes; mit einem anderen Branch kommen in keinem Repo offene Änderungen mit. Sie hält dafür kurz an.",
  "“{base}” is not an instance of this project — main and any ready copy can be the base.": "„{base}“ ist keine Instanz dieses Projekts — als Basis gehen Haupt und jede bereite Kopie.",
  "{who} no longer exists — choose another base.": "{who} gibt es nicht mehr — wähle eine andere Basis.",
  "{who} is not ready right now — a copy can only be made from a ready instance. If it is stopped, start it first; otherwise wait until it is ready, or choose another base.": "{who} ist gerade nicht bereit — eine Kopie entsteht nur aus einer bereiten Instanz. Ist sie gestoppt, starte sie zuerst; sonst warte, bis sie bereit ist, oder wähle eine andere Basis.",
  "Main is stopped — no copy can be made without a running main instance (not even from another copy). Start main in this list, then create the copy.": "Haupt ist gestoppt — ohne laufendes Haupt entsteht keine Kopie (auch nicht aus einer anderen Kopie). Starte Haupt in dieser Liste, dann lege die Kopie an.",
  "cbase could not read the code state of {who} — without it, it is unclear which repos the copy carries. Try again or choose another base.": "Den Code-Stand von {who} konnte cbase nicht lesen — ohne ihn ist unklar, welche Repos die Kopie trägt. Versuche es erneut oder wähle eine andere Basis.",
  "Branch per repo": "Branch je Repo",
