  "On: subagents and workflow agents get this server with the same selection and the same cards. Off: only the main agent — a subagent asks it.": "An: Subagenten und Workflow-Agenten bekommen diesen Server mit derselben Wahl und denselben Karten. Aus: nur der Hauptagent — ein Subagent bittet ihn darum.",
