  "A channel is created when an agent writes to another coding chat.": "Ein Kanal entsteht, wenn ein Agent einem anderen Coding-Chat schreibt.",
  "This chat is not a target of the outer loop — it observes regular coding chats.": "Dieser Chat ist kein Ziel des Outer Loop — beobachtet werden normale Coding-Chats.",
  "Deselected for coding chats at the server (Coding → MCP)": "Am Server für Coding-Chats abgewählt (Coding → MCP)",
  "Reset the summarizer to the cbase template? Name, task, triggers and tools come from the template; provider, model, effort and “on” stay.": "Den Zusammenfasser auf die cbase-Vorlage zurücksetzen? Name, Auftrag, Auslöser und Werkzeuge kommen aus der Vorlage; Anbieter, Modell, Grad und „an“ bleiben.",
  "Active on every coding chat created after it took effect — turn it on for older chats one by one in their chat info.": "Aktiv auf jedem Coding-Chat, der angelegt wird, nachdem er wirksam wurde — ältere Chats schaltest du einzeln in ihrer Chat-Info ein.",
  "Tools from external systems through an MCP server. Creating it and its token live under Coding → MCP; which of its tools THIS outer loop agent gets, you choose here.": "Werkzeuge aus Fremdsystemen über einen MCP-Server. Anlegen und Token liegen unter Coding → MCP; welche seiner Werkzeuge DIESER Outer-Loop-Agent bekommt, wählst du hier.",
  "Approval marks": "Freigabe-Marken",
  "An agent runs a marked cbase tool only once you approve, change the parameters or reject in the chat — this applies to every agent of this workspace that selected it. An outer loop run leaves it out.": "Ein markiertes cbase-Werkzeug führt ein Agent erst aus, wenn du im Chat freigibst, die Parameter änderst oder ablehnst — das gilt jedem Agenten dieses Workspace, der es gewählt hat. Ein Lauf des Outer Loop lässt es fort.",
